export type TypographyScale = {
  xs: number;
  sm: number;
  base: number;
  lg: number;
  xl: number;
  '2xl': number;
  '3xl': number;
};

export type SpacingScale = {
  0: number;
  0.5: number;
  1: number;
  2: number;
  3: number;
  4: number;
  5: number;
  6: number;
  8: number;
  10: number;
  12: number;
  16: number;
};

export type FontWeights = {
  regular: number;
  medium: number;
  semibold: number;
  bold: number;
};

export type LineHeights = {
  tight: number;
  normal: number;
  relaxed: number;
};

export type BorderRadiusScale = {
  none: number;
  sm: number;
  md: number;
  lg: number;
  full: number;
};

export type LetterSpacingScale = {
  tight: number;
  normal: number;
  wide: number;
  wider: number;
};

export type PrimitiveTokens = {
  typography: TypographyScale;
  spacing: SpacingScale;
  fontWeights: FontWeights;
  lineHeights: LineHeights;
  borderRadius: BorderRadiusScale;
  letterSpacing: LetterSpacingScale;
};

export type ColorTokens = {
  foreground: string;
  background: string;
  muted: string;
  mutedForeground: string;
  primary: string;
  primaryForeground: string;
  border: string;
  accent: string;
  destructive: string;
  success: string;
  warning: string;
  info: string;
};

export type TypographyTokens = {
  body: {
    fontFamily: string;
    fontSize: number;
    lineHeight: number;
  };
  heading: {
    fontFamily: string;
    fontWeight: number;
    lineHeight: number;
    fontSize: {
      h1: number;
      h2: number;
      h3: number;
      h4: number;
      h5: number;
      h6: number;
    };
  };
};

export type SpacingTokens = {
  page: {
    marginTop: number;
    marginRight: number;
    marginBottom: number;
    marginLeft: number;
  };
  sectionGap: number;
  paragraphGap: number;
  componentGap: number;
};

export type PageTokens = {
  size: 'A4' | 'LETTER' | 'LEGAL';
  orientation: 'portrait' | 'landscape';
};

export type PdfcnTheme = {
  name: string;
  primitives: PrimitiveTokens;
  colors: ColorTokens;
  typography: TypographyTokens;
  spacing: SpacingTokens;
  page: PageTokens;
};

import type { ComputedRef, InjectionKey } from 'vue';
import type { PdfcnTheme } from '@/lib/pdfcn/pdf-themes';
import { computed, inject } from 'vue';
import { professionalTheme } from '@/lib/pdfcn/themes/professional';

export const pdfcnThemeKey: InjectionKey<ComputedRef<PdfcnTheme>> = Symbol('pdfcn-theme');

export function usePdfcnTheme(): ComputedRef<PdfcnTheme> {
  return inject(
    pdfcnThemeKey,
    computed(() => professionalTheme),
  );
}

import type { ColorTokens } from '@/lib/pdfcn/pdf-themes';

export const THEME_COLOR_KEYS = [
  'foreground',
  'background',
  'muted',
  'mutedForeground',
  'primary',
  'primaryForeground',
  'border',
  'accent',
  'destructive',
  'success',
  'warning',
  'info',
] as const satisfies readonly (keyof ColorTokens)[];

export function resolveColor(value: string, colors: ColorTokens): string {
  for (const key of THEME_COLOR_KEYS) {
    if (value === key) return colors[key];
  }

  return value;
}

import type { Style } from '@formepdf/vue';

type PdfStyleInput = { [Key in keyof Style]?: Style[Key] | undefined };

export function mergePdfStyles(...styles: (PdfStyleInput | undefined)[]): Style {
  const merged: Style = {};
  for (const style of styles) {
    if (style) Object.assign(merged, style);
  }
  return merged;
}

